/*eslint-env node*/
/**
 * External dependencies
 */
const { Minimatch } = require( 'minimatch' );

// This is a simple webpack plugin to delete the JS files generated by MiniCssExtractPlugin.

function RemoveFilesPlugin( filePath = '' ) {
	// Strip leading ./ so the pattern matches webpack asset names (e.g. "build/foo.js").
	this.matcher = new Minimatch( filePath.replace( /^\.\//, '' ) );
}

RemoveFilesPlugin.prototype.apply = function ( compiler ) {
	compiler.hooks.thisCompilation.tap(
		'RemoveFilesPlugin',
		( compilation ) => {
			compilation.hooks.processAssets.tap(
				{
					name: 'RemoveFilesPlugin',
					stage: compiler.webpack.Compilation
						.PROCESS_ASSETS_STAGE_OPTIMIZE_TRANSFER,
				},
				() => {
					for ( const { name } of compilation.getAssets() ) {
						if ( this.matcher.match( name ) ) {
							compilation.deleteAsset( name );
						}
					}
				}
			);
		}
	);
};

module.exports = RemoveFilesPlugin;
